function normalizeTraffic(sources, config) {
  const normalizeText = v => String(v ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  const actionSlug = a => ({DC:'dc','DC_corredor-polones':'dc_corredor_polones',MET:'met',VD:'vd',GD:'gd',Workshop:'workshop'}[a]);
  const specs = new Map();
  for (const c of config) {
    const table = 'trafego_protagon_' + c.city + '_' + actionSlug(c.action);
    if (!actionSlug(c.action)) throw new Error('Estrategia desconhecida: ' + c.action);
    if (specs.has(table) && JSON.stringify(specs.get(table)) !== JSON.stringify(c.headers)) throw new Error('Colunas diferentes para ' + table);
    specs.set(table, c.headers);
  }
  const numericHeaders = new Set(['Valor Gasto','Impressões','Alcance','Cliques','Visitas ao Perfil','Page Views','Checkouts','Thruplays','View 3s','View 25%','View 50%','View 75%','View 95%']);
  const idHeaders = ['ID CAMPANHA','ID CONJUNTO','ID ANÚNCIO'];
  const byTable = new Map([...specs.keys()].map(t=>[t,new Map()]));
  const review = [];
  const summary = {linhas_lidas:0,duplicadas_na_origem:0,duplicadas_com_divergencia:0,linhas_em_revisao:0,linhas_preparadas:0,tabelas:{}};
  function parseDate(v) {
    if (typeof v === 'number' && Number.isFinite(v) && Number.isInteger(v) && v >= 36526 && v <= 109574) return new Date(Date.UTC(1899,11,30)+v*86400000).toISOString().slice(0,10);
    const s=String(v??'').trim();
    let m=s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if(!m){const br=s.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);if(br)m=[s,br[3],br[2],br[1]];}
    if(!m)throw new Error('Data invalida: '+s);
    const iso=m[1]+'-'+m[2]+'-'+m[3];
    if(new Date(iso+'T00:00:00Z').toISOString().slice(0,10)!==iso)throw new Error('Data inexistente: '+s);
    return iso;
  }
  function reviewRow(reason, source, line, record, details) {
    review.push({motivo:reason,planilha_id:source.id,aba:source.tab,linha:line,praca_origem:source.city,acao:source.action,dados:record,detalhes:details});
  }
  for (let si=0;si<sources.length;si++) {
    const source=sources[si];const cfg=config.find(c=>c.id===source.id&&c.gid===source.gid);
    if(!cfg)throw new Error('Fonte nao cadastrada');
    const values=source.values;
    if(!Array.isArray(values)||values.length===0)throw new Error('Cabecalho ausente: '+cfg.title+' / '+cfg.tab);
    const headers=values[0].map(v=>String(v??'').trim());
    while(headers.length&&headers.at(-1)==='')headers.pop();
    if(JSON.stringify(headers)!==JSON.stringify(cfg.headers))throw new Error('Cabecalhos mudaram em '+cfg.title+' / '+cfg.tab+'. Nenhum lote desta execucao sera enviado.');
    for(let ri=1;ri<values.length;ri++) {
      const cells=values[ri];
      if(!cells.some(v=>v!==null&&v!==undefined&&v!==''))continue;
      summary.linhas_lidas++;
      const raw=Object.fromEntries(headers.map((h,i)=>[h,cells[i]??null]));
      let record={};
      try {
        if(cells.slice(headers.length).some(v=>v!==null&&v!==undefined&&v!==''))throw new Error('Valores sem cabecalho');
        for (const h of headers) {
          const v=raw[h];
          if(h==='Data'){record[h]=parseDate(v);continue;}
          if(idHeaders.includes(h)){
            if(typeof v==='number'&&!Number.isSafeInteger(v))throw new Error('ID numerico sem precisao; formate o ID como texto no Sheets');
            const id=String(v??'').trim();if(!/^\d+$/.test(id))throw new Error('ID ausente ou invalido: '+h);
            record[h]=id;continue;
          }
          if(numericHeaders.has(h)){
            if(v===null||v===undefined||v===''){record[h]=null;continue;}
            if(typeof v!=='number'||!Number.isFinite(v)||v<0)throw new Error('Metrica nao numerica ou negativa: '+h);
            if(h!=='Valor Gasto'&&!Number.isSafeInteger(v))throw new Error('Contagem invalida: '+h);
            record[h]=v;continue;
          }
          if(typeof v==='string'&&/^#(REF!|VALUE!|N\/A|ERROR!|DIV\/0!|NAME\?)/.test(v))throw new Error('Erro de formula em '+h);
          record[h]=v===null||v===undefined||v===''?null:String(v);
        }
        if(!record['NOME DA CAMPANHA'])throw new Error('Campanha sem nome');
      } catch(error) {reviewRow('linha_invalida',cfg,ri+1,raw,{erro:error.message});continue;}
      const campaign=normalizeText(record['NOME DA CAMPANHA']);const cities=[];
      if(campaign.includes('e035'))cities.push('joinville');
      if(campaign.includes('e037'))cities.push('porto_alegre');
      if(/e038|goias|goiania/.test(campaign))cities.push('goiania');
      if(/e039|sao[ _-]+paulo/.test(campaign))cities.push('sao_paulo');
      if(cities.length>1){reviewRow('praca_ambigua',cfg,ri+1,record,{pracas_detectadas:cities});continue;}
      const city=cities[0]??cfg.city;
      const table='trafego_protagon_'+city+'_'+actionSlug(cfg.action);
      const targetHeaders=specs.get(table);
      if(!targetHeaders){reviewRow('destino_nao_cadastrado',cfg,ri+1,record,{tabela:table});continue;}
      const extra=headers.filter(h=>!targetHeaders.includes(h)&&record[h]!==null);
      if(extra.length){reviewRow('colunas_incompativeis_no_destino',cfg,ri+1,record,{tabela:table,colunas:extra});continue;}
      const ordered=Object.fromEntries(targetHeaders.map(h=>[h,record[h]??null]));
      ordered._origem_planilha=cfg.id;ordered._origem_aba=cfg.tab;ordered._origem_linha=ri+1;
      const key=[ordered.Data,...idHeaders.map(h=>ordered[h])].join('|');
      const old=byTable.get(table).get(key);
      if(old){
        summary.duplicadas_na_origem++;
        const diffs=targetHeaders.filter(h=>h!=='Creative Thumbnail'&&old[h]!==ordered[h]);
        if(diffs.length){summary.duplicadas_com_divergencia++;reviewRow('duplicidade_com_divergencia',cfg,ri+1,ordered,{tabela:table,colunas:diffs,primeiros_valores:Object.fromEntries(diffs.map(h=>[h,old[h]]))});}
      }else byTable.get(table).set(key,ordered);
    }
  }
  const tables={};
  for (const [table,records] of byTable){tables[table]=[...records.values()];summary.tabelas[table]=records.size;summary.linhas_preparadas+=records.size;}
  tables.trafego_protagon_revisao=review;summary.linhas_em_revisao=review.length;
  return {tables,summary};
}

